window.COZINHA_RECIPES=(window.COZINHA_RECIPES||[]).concat([{"id":"mingau-fuba-coco","title":"Mingau de fubá com coco","category":"Preparações cremosas sem lactose","image":"data:image/webp;base64,","minutes":20,"servings":2,"difficulty":"Fácil","tagline":"Creme morno e encorpado de fubá, coco e canela.","ingredients":[{"name":"fubá fino sem glúten","qty":3,"unit":"col. (sopa)"},{"name":"água","qty":1,"unit":"xíc."},{"name":"leite de coco sem açúcar","qty":1,"unit":"xíc."},{"name":"banana madura amassada","qty":0.5,"unit":"un"},{"name":"canela","qty":0.25,"unit":"col. (chá)"}],"steps":["Dissolva o fubá na água fria dentro de uma panela.","Junte o leite de coco e leve ao fogo baixo, mexendo continuamente.","Cozinhe por 12 a 15 minutos, até perder o sabor de fubá cru e engrossar.","Misture a banana amassada, cozinhe mais 2 minutos e finalize com canela."],"tip":"A banana adoça naturalmente; não é uma receita sem açúcares totais.","imageAlt":"Fotografia ilustrativa de Mingau de fubá com coco","reviewed":false,"verifiedInKitchen":false,"sourceType":"Preparo clássico adaptado; requer validação culinária","notes":"","caloriesEstimate":585},{"id":"omelete-tomate","title":"Omelete de tomate e cebola","category":"Café da manhã","image":"data:image/webp;base64,","minutes":12,"servings":1,"difficulty":"Fácil","tagline":"Omelete dobrado com tomate fresco e cebola.","ingredients":[{"name":"ovo","qty":2,"unit":"un"},{"name":"tomate sem sementes picado","qty":0.5,"unit":"un"},{"name":"cebola picada","qty":2,"unit":"col. (sopa)"},{"name":"azeite","qty":1,"unit":"col. (chá)"},{"name":"sal","qty":1,"unit":"pitada"},{"name":"salsinha","qty":1,"unit":"col. (chá)"}],"steps":["Bata os ovos com sal e salsinha.","Aqueça o azeite e refogue a cebola por 1 minuto.","Acrescente o tomate, deixe evaporar parte da água e espalhe o recheio.","Despeje os ovos batidos, tampe e cozinhe em fogo baixo até firmar.","Dobre ao meio e sirva sem partes líquidas no centro."],"tip":"Retirar as sementes do tomate ajuda a não encharcar a omelete.","imageAlt":"Fotografia ilustrativa de Omelete de tomate e cebola","reviewed":false,"verifiedInKitchen":false,"sourceType":"Preparo clássico adaptado; requer validação culinária","notes":"","caloriesEstimate":235},{"id":"pao-frigideira-polvilho","title":"Pão de frigideira de polvilho","category":"Pães, bolos e massas","image":"data:image/webp;base64,","minutes":20,"servings":1,"difficulty":"Fácil","tagline":"Pãozinho macio de polvilho e batata, feito na frigideira.","ingredients":[{"name":"batata cozida e bem amassada","qty":0.5,"unit":"xíc."},{"name":"polvilho doce","qty":3,"unit":"col. (sopa)"},{"name":"ovo","qty":1,"unit":"un"},{"name":"azeite","qty":1,"unit":"col. (chá)"},{"name":"fermento químico sem glúten","qty":0.25,"unit":"col. (chá)"},{"name":"sal","qty":1,"unit":"pitada"}],"steps":["Misture a batata fria, ovo, azeite e sal.","Acrescente o polvilho e o fermento até obter massa espessa e homogênea.","Aqueça frigideira antiaderente pequena e untada em fogo bem baixo.","Despeje a massa, tampe e cozinhe por 5 a 7 minutos de cada lado ou até o centro ficar totalmente firme."],"tip":"Se necessário, divida a massa em dois discos para cozinhar melhor.","imageAlt":"Fotografia ilustrativa de Pão de frigideira de polvilho","reviewed":false,"verifiedInKitchen":false,"sourceType":"Preparo clássico adaptado; requer validação culinária","notes":"","caloriesEstimate":910}]);
